@rule("s2", "s22", otherwise="Contradiction")
def contradiction_check():
    return "Receiving Party shall not reverse engineer any objects which embody Disclosing Party's Confidential Information." in s22.text

@rule("s3", "s22", otherwise="NotMentioned")
def reverse_engineering_prohibition():
    return "Recipient will not modify, reverse engineer, create other works from, or disassemble any software programs contained in the CI without Discloser’s prior written consent." in s22.text

@rule("s22", "s22", otherwise="NotMentioned")
def query_target():
    return "Receiving Party shall not reverse engineer any objects which embody Disclosing Party's Confidential Information."

query = contradiction_check() if contradiction_check() == "Contradiction" else (reverse_engineering_prohibition() if reverse_engineering_prohibition() == "NotMentioned" else query_target())
